package com.vandorlabs.screen;
import com.vandorlabs.persistence.*;
/** Reserved Navigation selection preserves legacy Chip, controls and serialized artwork indices. */
public final class ScreenNavigationAppearanceTest {
 public static void main(String[] args){int checks=0;ScreenData scalar=new ScreenData("default",false,2,true,1,"default","default",-1,false,0,false,0);for(ScreenFamily family:ScreenFamily.values())for(int raw:new int[]{-5,-4})for(int power:new int[]{0,7,15})for(boolean inverted:new boolean[]{false,true}){DisplayActivationData active=DisplayActivationData.LEGACY.configure(2,0,12,2,1,n->n>=0).configure(2,3,23,1,2,n->n>=0);ScreenAppearance value=ScreenAppearance.compute(family,scalar,active,inverted,raw,raw,false,false,false,power,true,3,4);need(value.primarySurface==raw&&value.secondarySurface==raw,"reserved selection survives activation "+raw);need(value.sharedArtwork==raw,"saved shared index stable");checks+=2;}for(int raw:new int[]{-5,-4,0}){ScreenJoinSignature a=new ScreenJoinSignature(0,false,false,false,-1,-1,true,false,0,0,raw,new int[12]);need(a.editEligible(ScreenFamily.SCREEN),"joined reserved mode eligible");need(a.editMatches(new ScreenJoinSignature(2,true,false,false,-1,-1,true,false,0,0,raw,new int[12])),"artwork join independent power");checks+=2;}boolean refused=false;try{ScreenAppearance.compute(ScreenFamily.SCREEN,scalar,DisplayActivationData.LEGACY,false,-6,-1,false,false,false,0,false,0,0);}catch(IllegalArgumentException expected){refused=true;}need(refused,"future reserved values remain refused");System.out.println("ScreenNavigationAppearanceTest PASS checks="+(checks+1)+" nav-5/chip-4/activation/join/unknown");}
 private static void need(boolean b,String s){if(!b)throw new AssertionError(s);}
}
